source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value not in (2, 8):
                counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2, 8)]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    out = [[bg for _ in range(w)] for _ in range(h)]
    if rows:
        line = rows[0]
        for r in range(h):
            if r == line: out[r] = [2] * w
        if r1 < line:
            nr0 = line - (r1-r0) - 1
            for r in range(r0, r1+1):
                for c in range(c0, c1+1): out[nr0+r-r0][c] = grid[r][c]
            mark = nr0 - 1
        else:
            nr0 = line + 1
            for r in range(r0, r1+1):
                for c in range(c0, c1+1): out[nr0+r-r0][c] = grid[r][c]
            mark = nr0 + (r1-r0) + 1
        if 0 <= mark < h: out[mark] = [8] * w
        return out
    if cols:
        line = cols[0]
        for r in range(h): out[r][line] = 2
        if c1 < line:
            nc0 = line - (c1-c0) - 1
            for r in range(r0, r1+1):
                for c in range(c0, c1+1): out[r][nc0+c-c0] = grid[r][c]
            mark = nc0 - 1
        else:
            nc0 = line + 1
            for r in range(r0, r1+1):
                for c in range(c0, c1+1): out[r][nc0+c-c0] = grid[r][c]
            mark = nc0 + (c1-c0) + 1
        if 0 <= mark < w:
            for r in range(h): out[r][mark] = 8
        return out
    return [row[:] for row in grid]
'''
